mapper.select:
SELECT `id` `id`, `object_type` `objectType`, `device_object` `deviceObject`, `open_gate` `openGate`, `brightness` `brightness`, `result` `result`, `control_time` `controlTime`, `time_control_id` `timeControlId`, `object_name` `objectName` FROM `time_control_log`
and `control_time` between #{startTime} and #{endTime}
order by `create_time` DESC
